/**
 * Robustness scenarios — reproducible edge cases for the defence and for regression tests.
 *
 * Each scenario is generated by running the REAL engine and planner on a simulated learner
 * (synthetic, clearly labelled demo data), so what the jury sees is the production code path,
 * not a mock-up. The same builders are used by `jury-scenarios.test.ts`.
 */
import { buildDemoHistory, DEMO_PERSONA, type DemoData, type DemoOptions } from './demo';
import type { SimUser } from './simulate';
import { applyDispute, makeDispute, pickDisputedSession } from './pushback';
import { checkMessage } from './coach/guardrails';
import { templateReply, type CoachContext } from './coach/chat';
import { computeCollabScore } from './collaboration';
import { taskForDimension } from './dimensions';
import { detectPlateau } from './formats';
import { profileInsights } from './insights';
import { generateDailyPlan } from './planner';
import { project } from './projection';
import { isMashedSession } from './quality';
import { createRng } from './rng';
import { finalizeSession } from './session';
import { simulateRun } from './simulate';
import { detectAsymmetry } from './tiers';
import { currentProfile, dimensionHistory, modelFor } from './twin';

export type ScenarioId = 'masher' | 'plateau' | 'why' | 'pushback' | 'fortune' | 'asymmetric';

/** Consistently average, no trend: true ability flat at the middle of every ladder. */
export const PLATEAU_PERSONA: SimUser = {
  theta: { attention: 0, memory: 0, speed: 0, inhibition: 0, flexibility: 0, reasoning: 0 },
  growth: {},
  rtScale: 1,
  lapseRate: 0.02,
  interruptRate: 0,
};

/** Flawless at logic, failing completely at attention, ordinary elsewhere. */
export const ASYMMETRIC_PERSONA: SimUser = {
  theta: { attention: -5, memory: 0.1, speed: 0.3, inhibition: 0, flexibility: 0.2, reasoning: 5 },
  growth: { memory: 0.3, speed: 0.2, inhibition: 0.3, flexibility: 0.3 },
  rtScale: 1,
  lapseRate: 0,
  interruptRate: 0,
};

export interface ScenarioDef {
  id: ScenarioId;
  title: string;
  /** What the jury tests. */
  tests: string;
  challenge: string;
  /** What the system does, step by step. */
  response: string[];
  /** Question to ask the coach, when the scenario is a conversation. */
  prompt?: string;
  /** Where to go after loading. */
  route: string;
  routeLabel: string;
  data: DemoOptions & { seed?: number };
}

