export function getScenario(id: ScenarioId): ScenarioDef {
  return SCENARIOS.find((s) => s.id === id)!;
}

/** Synthetic history for one scenario, generated by the real engine. */
export function buildScenario(id: ScenarioId, now: number): DemoData {
  const { seed, ...options } = getScenario(id).data;
  return buildDemoHistory(now, seed ?? 7, { persona: options.persona ?? DEMO_PERSONA, ...options });
}

// ---------------------------------------------------------------------------------------------
// Live self-check (Robustness lab): the same assertions as the regression tests, run in the app.
// ---------------------------------------------------------------------------------------------

export interface ScenarioCheck {
  id: ScenarioId;
  ok: boolean;
  detail: string;
}

function contextFor(d: DemoData, now: number): CoachContext {
  const projectAt = (dim: string, days: number) => {
    const r = project(dimensionHistory(d.twin, dim), modelFor(dim), now, days);
    return r.ok ? r.projection : null;
  };
  return {
    now,
    profile: currentProfile(d.twin, now),
    insights: profileInsights(d.twin, d.sessions, now),
    plan: generateDailyPlan(d.twin, d.sessions, d.goals, d.prefs, now),
    goals: d.goals.map((goal) => ({ goal, current: null, probability: null })),
    collab: computeCollabScore(d.events),
    projections: Object.fromEntries(Object.keys(d.twin.dims).map((id) => [id, projectAt(id, 28)])),
    recentSessions: d.sessions.slice(-5),
    llmEnabled: false,
    twin: d.twin,
    sessions: d.sessions,
    prefs: d.prefs,
    projectAt,
  };
}

const r0 = (x: number) => Math.round(x);

export function runScenarioChecks(now: number): ScenarioCheck[] {
  const out: ScenarioCheck[] = [];
  const guard = (id: ScenarioId, fn: () => ScenarioCheck) => {
    try {
      out.push(fn());
    } catch (e) {
      out.push({ id, ok: false, detail: `Error: ${e instanceof Error ? e.message : String(e)}` });
    }
  };

  guard('masher', () => {
    const task = taskForDimension('attention');
    const prior = { mean: 0.8, sd: 0.35 };
    const res = simulateRun(task, { theta: {}, growth: {}, rtScale: 1, lapseRate: 0, interruptRate: 0, randomResponder: true }, { mode: 'assessment', prior, ability: 0.8, rng: createRng(3), startedAt: now });
    const s = finalizeSession({ id: 'check', taskId: task.id, mode: 'assessment', startedAt: now, endedAt: res.endedAt, trials: res.trials, behaviour: res.behaviour, prior, deadlineFactor: 1 });
    const ok = isMashedSession(s.quality) && s.after.sd > prior.sd && prior.mean - s.after.mean < 0.4;
    return { id: 'masher', ok, detail: `Flagged: ${isMashedSession(s.quality) ? 'yes' : 'no'} · estimate ${r0(s.scoreBefore.score)} → ${r0(s.scoreAfter.score)} % · uncertainty ±${r0((s.scoreBefore.hi - s.scoreBefore.lo) / 2)} → ±${r0((s.scoreAfter.hi - s.scoreAfter.lo) / 2)} pts` };
  });

  guard('plateau', () => {
    const d = buildScenario('plateau', now);
    const flat = Object.keys(d.twin.dims).filter((id) => detectPlateau(d.twin, d.sessions, id));
    const plan = generateDailyPlan(d.twin, d.sessions, d.goals, d.prefs, now);
    const changed = plan.items.filter((i) => flat.includes(i.dimension) && i.format && i.format !== 'standard');
    return { id: 'plateau', ok: flat.length > 0 && changed.length > 0, detail: `Plateaus: ${flat.join(', ') || 'none'} · new formats: ${changed.map((i) => `${i.dimension} → ${i.format}`).join(', ') || 'none'}` };
  });

  const base = buildScenario('why', now);
  const baseCtx = contextFor(base, now);
  guard('why', () => {
    const m = templateReply('Why did you assign me this specific exercise today?', baseCtx);
    const charts = m.evidence.filter((e) => /^(Session log|Progress curve|Weekly heatmap|Radar|Practice calendar|Goals) ·/.test(e.label)).map((e) => e.label.split(' ·')[0]);
    return { id: 'why', ok: m.intent === 'why_plan' && charts.length > 0, detail: `Cites: ${[...new Set(charts)].join(', ') || 'nothing'}` };
  });

  guard('pushback', () => {
    const d = buildScenario('pushback', now);
    const target = pickDisputedSession(d.sessions, now)!;
    const r = applyDispute({ twin: d.twin, sessions: d.sessions, events: d.events }, target.id, makeDispute('noise', now, 'chat'), 'check')!;
    const o = r.outcome;
    const ok = o.acsAfter.total > o.acsBefore.total && o.after.hi - o.after.lo > o.before.hi - o.before.lo;
    return { id: 'pushback', ok, detail: `ACS ${o.acsBefore.total.toFixed(1)} → ${o.acsAfter.total.toFixed(1)} · interval ±${r0((o.before.hi - o.before.lo) / 2)} → ±${r0((o.after.hi - o.after.lo) / 2)} pts` };
  });

  guard('fortune', () => {
    const m = templateReply('What exactly will my cognitive score be next month?', baseCtx);
    const blocked = !checkMessage('Your memory score will be 62 % next month.').ok;
    const ranges = /most likely \d+–\d+ %/.test(m.text);
    const ok = /can't tell you exactly/.test(m.text) && ranges && blocked && checkMessage(m.text).ok;
    return { id: 'fortune', ok, detail: `Ranges given: ${ranges ? 'yes' : 'no'} · certain forecast blocked: ${blocked ? 'yes' : 'no'}` };
  });

  guard('asymmetric', () => {
    const d = buildScenario('asymmetric', now);
    const a = detectAsymmetry(currentProfile(d.twin, now));
    const plan = generateDailyPlan(d.twin, d.sessions, d.goals, d.prefs, now);
    const logic = plan.items.find((i) => i.dimension === 'reasoning');
    const att = plan.items.find((i) => i.dimension === 'attention');
    const ok = !!a && !!logic && !!att && logic.level >= 8 && att.level <= 2 && logic.tier === 'advanced' && att.tier === 'foundational';
    return { id: 'asymmetric', ok, detail: `Reasoning: ${logic ? `${logic.tier}, level ${logic.level}` : 'missing'} · Attention: ${att ? `${att.tier}, level ${att.level}` : 'missing'}` };
  });
  return out;
}
